--   security_code = usc；security_name = 映射 name_en（英文源名）；security_name_cn = name（中文名）；
--   security_name_full = name_en
--   currency_type = USD；init_date = 20000000（未上市/未知占位）；timezone = -04:00；tz = America/New_York
--   flag_enable = '0'（待人工启用）；provider = FTMM
--
-- 统计：
--   待插入 417 行（批次共 417 行；映射命中 417，未命中 0，已兜底生成）
--   market_code 分布：0 215、1315 151、1316 44、1317 7
--   security_type 分布：ETF 83、Stock 334
--   自检：usc 无重复；无 (exchange_code, security_code) 冲突
--
-- 幂等：单事务；每 500 行一条 INSERT ... ON CONFLICT DO NOTHING，
--   命中主键/唯一约束整行跳过，不覆盖任何已存在行；
--   gmt_create / gmt_update 由默认值与 vq_set_gmt_update() 触发器维护。
-- 迁移策略：单事务（BEGIN/COMMIT），由应用启动时的迁移链自动执行并记入 schema_version；
-- =======================================================================

BEGIN;

DO $$
BEGIN
    IF (SELECT count(*) FROM information_schema.columns WHERE table_schema = 'public'
          AND table_name = 'finv_security'
          AND column_name IN ('usc','security_name_full','provider','remark')) < 4 THEN
        RAISE EXCEPTION 'finv_security 缺列（需 V200005 建表 + V200082 扩列）';
    END IF;
END $$;

ON CONFLICT DO NOTHING;

DO $$
DECLARE v int;
BEGIN
    SELECT count(*) INTO v FROM public.finv_security WHERE remark = '20261109-线上缺失证券补齐';
    RAISE NOTICE '本批次 finv_security 现有行数：%', v;
END $$;

COMMIT;
